export type GetOauth2AuthorizeData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Client identifier (required)
         */
        client_id: string;
        /**
         * Redirect URI (required)
         */
        redirect_uri: string;
        /**
         * Response type, must be 'code' (required)
         */
        response_type: string;
        /**
         * Requested scope (optional)
         */
        scope?: string;
        /**
         * Opaque value to maintain state between request and callback (recommended)
         */
        state?: string;
        /**
         * PKCE code challenge (RFC 7636). Required for public clients when auth.require_pkce_for_public is enabled (default true).
         */
        code_challenge?: string;
        /**
         * PKCE code challenge method ('plain' or 'S256')
         */
        code_challenge_method?: string;
        /**
         * OIDC nonce (anti-replay). Echoed in the id_token when openid scope is requested.
         */
        nonce?: string;
        /**
         * OIDC prompt values, space-separated (none|login|consent). none forbids UI; login forces re-auth; consent forces the consent screen. Combining none with another value returns 400. (OIDC Core §3.1.2.1)
         */
        prompt?: string;
        /**
         * Maximum allowable age in seconds of the user's authentication. If the session auth_time is older, re-authentication is forced.
         */
        max_age?: number;
        /**
         * Organization context hint (v1.4.0): integer id or slug of the organization this authorization is made in. Accepted only when the user is a current member and the client belongs to that organization; every rejection renders the same inline 400 (no redirect). Combine with the org scope to receive org_ctx claims.
         */
        org_id?: string;
    };
    url: '/oauth2/authorize';
};

export type GetOauth2AuthorizeErrors = {
    /**
     * Invalid request (malformed prompt, missing required params, or an invalid/unauthorized org_id)
     */
    400: unknown;
};

export type PostOauth2ConsentData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Client identifier (required)
         */
        client_id: string;
        /**
         * User identifier (required)
         */
        user_id: string;
        /**
         * Requested scope to consent (required)
         */
        scope: string;
        /**
         * Redirect URI (required)
         */
        redirect_uri: string;
        /**
         * Opaque value to maintain state
         */
        state?: string;
        /**
         * Action to perform: 'approve' or 'deny' (required)
         */
        action: 'approve' | 'deny';
        /**
         * Server-minted one-shot CSRF nonce from the authorize->consent redirect (required; consumed on use)
         */
        consent_csrf: string;
    };
    url: '/oauth2/consent';
};

export type PostOauth2ConsentErrors = {
    /**
     * Missing/expired/mismatched consent_csrf nonce, or (deny) redirect_uri not registered for the client (VALIDATION_INVALID_INPUT / VALIDATION_REDIRECT_URI_NOT_REGISTERED)
     */
    400: unknown;
    /**
     * No authenticated session (AUTH_SESSION_REQUIRED), or the session is paused at the MFA challenge (AUTH_MFA_REQUIRED, #144: consent must not be granted on amr="pwd" for an MFA-required account)
     */
    401: unknown;
    /**
     * user_id does not match the authenticated session (AUTHZ_ACCESS_DENIED), or the account is flagged must_change_password (AUTH_PASSWORD_CHANGE_REQUIRED, #145)
     */
    403: unknown;
};

export type GetOauth2AuthorizeContextData = {
    body?: never;
    path?: never;
    query: {
        client_id: string;
    };
    url: '/oauth2/authorize-context';
};

export type GetOauth2AuthorizeContextErrors = {
    /**
     * Missing client_id
     */
    400: unknown;
    /**
     * Unknown or soft-deleted client
     */
    404: unknown;
};

export type GetOauth2AuthorizeContextResponses = {
    /**
     * Application display name + branding
     */
    200: {
        client_name?: string;
        /**
         * Client brand image (absent when unset)
         */
        logo_uri?: string;
        org?: {
            org_name?: string;
            logo_uri?: string;
            primary_color?: string;
        } | null;
    };
};

export type GetOauth2AuthorizeContextResponse = GetOauth2AuthorizeContextResponses[keyof GetOauth2AuthorizeContextResponses];

export type GetOauth2ConsentContextData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Server-minted one-shot CSRF nonce from the authorize->consent redirect (required; validated, not consumed)
         */
        consent_csrf: string;
        /**
         * The client the consent flow is for (required)
         */
        client_id: string;
        /**
         * The flow's redirect_uri; must be registered for client_id (required)
         */
        redirect_uri: string;
        /**
         * The flow's state value; resolves the server-stashed org binding (no binding or unknown state -> org is null)
         */
        state?: string;
        /**
         * The session user id echoed from the consent URL (required; must match the session)
         */
        user_id: string;
        /**
         * P1-1 (#279): the flow's requested scopes (space- or comma-separated); when present, the response carries localized descriptions per scope from the oauth2_scopes catalog
         */
        scope?: string;
        /**
         * P1-1 (#279): page locale (a "zh*" prefix selects the zh-CN description column; anything else selects the en column)
         */
        locale?: string;
    };
    url: '/oauth2/consent/context';
};

export type GetOauth2ConsentContextErrors = {
    /**
     * Missing/unknown/expired consent_csrf, missing client_id/redirect_uri, or redirect_uri not registered for client_id (VALIDATION_INVALID_INPUT / VALIDATION_REDIRECT_URI_NOT_REGISTERED)
     */
    400: unknown;
    /**
     * No authenticated session (AUTH_SESSION_REQUIRED)
     */
    401: unknown;
    /**
     * user_id does not match the authenticated session (AUTHZ_ACCESS_DENIED)
     */
    403: unknown;
};

export type GetOauth2ConsentContextResponses = {
    /**
     * Consent context (owner_name empty for admin-seeded clients; org null for flows without an org binding)
     */
    200: {
        /**
         * Attribution label: org name for org apps, the creator's display name for personal apps; empty for admin-seeded clients and on storage degradation.
         */
        owner_name?: string;
        /**
         * P1-1: the client's display name (falls back to the client_id).
         */
        client_name?: string;
        /**
         * P1-1: the client's brand image (absent when unset).
         */
        logo_uri?: string;
        /**
         * P1-1: localized descriptions for the scopes named in the `scope` parameter (unknown names omitted; the frontend dictionary is the missing-key fallback).
         */
        scope_descriptions?: Array<{
            scope?: string;
            description_i18n?: string;
        }>;
        /**
         * The org context this flow is authorizing under (design 2.1); null when the flow has no org binding. P1-1 adds the org brand fields (absent when unset).
         */
        org?: {
            org_id?: number;
            org_name?: string;
            logo_uri?: string;
            primary_color?: string;
        } | null;
    };
};

export type GetOauth2ConsentContextResponse = GetOauth2ConsentContextResponses[keyof GetOauth2ConsentContextResponses];

