export type GetOauth2EndSessionData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Previously issued id_token hinting at the client/session to terminate. Signature-verified against the OP key set (#78); a bad or expired signature, wrong issuer, or a subject contradicting the current session yields 400 AUTH_INVALID_ID_TOKEN_HINT. The aud claim (string or array, RFC 7519 §4.1.3) identifies the client(s) for validating post_logout_redirect_uri; the first candidate owning the URI wins.
         */
        id_token_hint?: string;
        /**
         * URI to redirect to after logout. Must be registered for the id_token_hint client; rejected with 400 otherwise.
         */
        post_logout_redirect_uri?: string;
        /**
         * RP self-identification when id_token_hint is absent (RP-Initiated Logout 1.0 §2.1). The post_logout_redirect_uri must be registered for this client (#88-3).
         */
        client_id?: string;
        /**
         * Opaque value echoed back to the post_logout_redirect_uri.
         */
        state?: string;
    };
    url: '/oauth2/end_session';
};

export type GetOauth2EndSessionErrors = {
    /**
     * Error Envelope. (a) id_token_hint failed verification/expired/issuer mismatch/session-subject mismatch/aud without a usable client identifier: AUTH_INVALID_ID_TOKEN_HINT; (b) post_logout_redirect_uri supplied without an id_token_hint: AUTH_INVALID_ID_TOKEN_HINT; (c) post_logout_redirect_uri not registered for any aud client of the verified hint: VALIDATION_REDIRECT_URI_NOT_REGISTERED.
     */
    400: ErrorEnvelope;
};

export type GetOauth2EndSessionError = GetOauth2EndSessionErrors[keyof GetOauth2EndSessionErrors];

export type GetOauth2EndSessionResponses = {
    /**
     * Logged out (no post_logout_redirect_uri supplied)
     */
    200: MessageResponse;
};

export type GetOauth2EndSessionResponse = GetOauth2EndSessionResponses[keyof GetOauth2EndSessionResponses];

export type PostOauth2EndSessionData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Previously issued id_token hint (signature-verified,
         */
        id_token_hint?: string;
        /**
         * RP self-identification when id_token_hint is absent (RP-Initiated Logout 1.0 §2.1). The post_logout_redirect_uri must be registered for this client (#88-3).
         */
        client_id?: string;
        /**
         * Registered post-logout redirect URI.
         */
        post_logout_redirect_uri?: string;
        /**
         * Opaque state value.
         */
        state?: string;
    };
    url: '/oauth2/end_session';
};

export type PostOauth2EndSessionErrors = {
    /**
     * Error Envelope: id_token_hint verification failure, or neither id_token_hint nor client_id supplied with a post_logout_redirect_uri (AUTH_INVALID_ID_TOKEN_HINT), or post_logout_redirect_uri not registered for the identifying client (VALIDATION_REDIRECT_URI_NOT_REGISTERED). See GET for full semantics.
     */
    400: ErrorEnvelope;
};

export type PostOauth2EndSessionError = PostOauth2EndSessionErrors[keyof PostOauth2EndSessionErrors];

export type PostOauth2EndSessionResponses = {
    /**
     * Logged out
     */
    200: MessageResponse;
};

export type PostOauth2EndSessionResponse = PostOauth2EndSessionResponses[keyof PostOauth2EndSessionResponses];

